with (p/'incheon_112_202510_monthly.csv').open('w') as f:
 cols=['month','station_id','aggregation','station_pressure_hpa','sea_level_pressure_hpa','air_temperature_c','relative_humidity_pct','pressure_elevation_m'];w=csv.DictWriter(f,fieldnames=cols);w.writeheader();w.writerow({k:fields[k] for k in cols})
assert (fields['station_pressure_hpa'],fields['sea_level_pressure_hpa'],fields['air_temperature_c'],fields['relative_humidity_pct'])==(1011.8,1020.0,16.4,77)
